-- CrossFit Symmetry website content, applied 2026-10-21 (site template launch). Coaches, class coaches, plans and services were set in the same session.

with g as (select id from gyms where slug='cfs')
update gym_sites s set content = $J${"levels": [["Beginner", "green"], ["Intermediate", "yellow"], ["Rx", "red"]], "today_title": "Today at Symmetry", "heads": {"community": {"eyebrow": "Community", "title": "Fun workouts for all levels", "desc": "Thirteen years in Milford. The workouts change every day; the people cheering you through the last rep do not."}, "classes": {"eyebrow": "Classes", "title": "Find your class", "desc": "Classes run an hour. Members reserve in the app; new faces can book a free class right here."}, "plans": {"eyebrow": "Plans", "title": "Pick how often you train", "desc": "Every plan is month to month with coached classes and weekend open gym. Unlimited adds Dandy Pro. Start with a free class and a coach helps you choose.", "chip": "Sample prices"}, "book": {"eyebrow": "Book online", "title": "Book your visit", "desc": "Your first class is free. Drop ins are free for visiting CrossFitters. Personal training and nutrition coaching are $60 an hour with the coach you choose."}, "coaches": {"eyebrow": "Coaches", "title": "Who's coaching your class", "desc": "Every class is led by a Symmetry coach. Times come straight from the class schedule. Book any of them for personal training."}, "faq": {"eyebrow": "FAQ", "title": "Frequently asked questions", "desc": "Still wondering about something? Text us and a coach will answer."}, "contact": {"eyebrow": "Contact", "title": "Talk to a coach", "desc": "Questions about a free class, drop ins, pricing or personal training? Text or call and a CFS coach gets right back to you."}, "store": {"eyebrow": "CFS store", "title": "Rep the blue and yellow", "desc": "Shirts, hoodies and gear in Symmetry colors. Order online and pick up at the front desk, free."}, "events": {"eyebrow": "CFS events", "title": "Mark your calendar", "desc": "Partner workouts, max out days, holiday WODs and Murph on Memorial Day. Friends and family welcome."}}, "pillars": [{"n": "3", "title": "Levels in every workout", "text": "Every class has a beginner, intermediate and Rx version. Everyone finishes together, and nobody gets left out."}, {"n": "auto:classes", "title": "Coached classes a week", "text": "A coach runs every class, teaches every movement and adjusts every weight. You never have to guess what to do."}, {"n": "Free", "title": "First class and drop ins", "text": "Your first class is on us, and visiting CrossFitters drop in free. Come see what the hype is about."}], "social_title": "Life at Symmetry", "schedule_note": "Ask us for kids and teen class times.", "programs": [{"ages": "Adults \u00b7 All levels", "title": "CrossFit classes", "text": "Varied, high intensity workouts that build strength and endurance, scaled to you."}, {"ages": "1 on 1 or small group", "title": "Personal training", "text": "Private or semi private coaching to reach your goals faster. Book it below."}, {"ages": "One on one \u00b7 Ongoing", "title": "Nutrition consulting", "text": "A plan for how you eat that fits your goals and your week, with regular check ins. Book a consult below."}, {"ages": "Ages 5 to 9 \u00b7 Teens \u00b7 Athletes", "title": "Kids, teens and sports", "text": "Helping kids move, grow and gain confidence, plus teen conditioning and sports performance."}], "included": ["Coached classes", "Weekend open gym", "Lift tracking in Dandy", "Dandy Pro with Unlimited"], "faq": [{"q": "Never done CrossFit?", "a": "Book a free class. A coach meets you 10 minutes early, shows you around and scales every movement for you."}, {"q": "When is the gym open?", "a": "During coached classes and weekend open gym. See the schedule above for this week's times."}, {"q": "Who gets a free drop in?", "a": "Anyone who trains CrossFit somewhere else. Visiting family in Milford? Come work out with us on the house."}, {"q": "What should I bring?", "a": "Water, training shoes and clothes you can move in. We have everything else."}], "directions_bold": "We are on the Route 131 side of the building.", "directions": "Lila Ave, just off US 50 and SR 131.", "about": "Milford's community gym. Rogue rigs, Echo bikes, Concept2 rowers and SkiErgs, and the best people in town.", "motto": "Achieve balance through fitness", "text_quick": [["Free class", "Hi! I'd like to try a free class. What times work this week?"], ["Drop in", "Hi! I'm visiting and want to drop in. Do I need to book?"], ["Pricing", "Hi! What does membership cost?"], ["Personal training", "Hi! I'm interested in personal training."], ["Murph", "Hi! Can I sign up for Murph?"]]}$J$::jsonb,
  brand = s.brand || $J${"vars": {"--bg": "#0A1430", "--panel": "#101D3A", "--panel2": "#162647", "--line": "#243760", "--fg": "#EEF2F8", "--muted": "#9AA8C2", "--accent": "#F7C531", "--accent-fg": "#0A1430", "--cta": "#F7C531", "--cta-fg": "#0A1430", "--brand-blue": "#2F6BFF"}, "vars_light": {"--bg": "#F2F5FB", "--panel": "#FFFFFF", "--panel2": "#E6ECF7", "--line": "#CFD8E8", "--fg": "#0A1430", "--muted": "#53617D", "--accent": "#1F57D6", "--accent-fg": "#FFFFFF", "--cta": "#F7C531", "--cta-fg": "#0A1430", "--brand-blue": "#1F57D6"}}$J$::jsonb,
  hero = $J${"eyebrow": "CrossFit Symmetry \u00b7 CFS \u00b7 Milford, Ohio \u00b7 Achieve balance through fitness", "headline": "Milford's best *community* gym.", "sub": "Fun, coached workouts for every level, seven days a week. First timers, former athletes, parents and 5:30am diehards all do the same workout, scaled to fit. Come for the workout. Stay for the people."}$J$::jsonb,
  links = s.links || $J${"map_query": "CrossFit Symmetry 1005 Lila Ave Milford OH 45150", "zip": "45150"}$J$::jsonb,
  seo = s.seo || '{"noindex": true, "title": "CrossFit Symmetry | CrossFit gym in Milford, OH", "description": "CrossFit Symmetry in Milford, Ohio. Coached classes for every level, seven days a week. Your first class is free."}'::jsonb,
  sections = s.sections || '{"events": false, "store": false, "workouts": true, "board": true, "social": true}'::jsonb,
  published = true
from g where s.gym_id = g.id;
